228	            }
229	        }
230	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	    }
232	
233	    /**
234	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
235	     * offending field is collected so the caller learns exactly which values must be supplied.
236	     *
237	     * @param ownerFieldsDto the submitted owner payload
238	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
239	     *         telephone is missing or blank
240	     */
241	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
242	        List<String> missingFields = new ArrayList<>();
243	        if (isBlank(ownerFieldsDto.getFirstName())) {
244	            missingFields.add("firstName");
245	        }
246	        if (isBlank(ownerFieldsDto.getLastName())) {
247	            missingFields.add("lastName");
248	        }
249	        if (isBlank(ownerFieldsDto.getAddress())) {
250	            missingFields.add("address");
251	        }
252	        if (isBlank(ownerFieldsDto.getCity())) {
253	            missingFields.add("city");
254	        }
255	        if (isBlank(ownerFieldsDto.getTelephone())) {
256	            missingFields.add("telephone");
257	        }
258	        if (!missingFields.isEmpty()) {
259	            throw new MissingOwnerFieldsException(missingFields);
260	        }
261	    }
262	
263	    private boolean isBlank(String value) {
264	        return value == null || value.isBlank();
265	    }
266	
267	    /**
268	     * Builds an owner's customer code, formatted '&lt;LAST3&gt;-&lt;NNNN&gt;'. LAST3 is the
269	     * upper-cased first three letters of the last name; NNNN is a global 4-digit zero-padded
270	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
271	     *
272	     * @param lastName the owner's last name
273	     * @return the formatted customer code
274	     */
275	    private String generateCustomerCode(String lastName) {
276	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
277	        int sequence = this.clinicService.findAllOwners().size() + 1;
278	        return String.format("%s-%04d", last3, sequence);
279	    }
280	
281	    /**
282	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
283	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
284	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
285	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
286	     * stored and returned.
287	     *
288	     * @param telephone the raw telephone value from the request
289	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
290	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
291	     */
292	    private String normalizeTelephone(String telephone) {
293	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
294	        String e164;
295	        if (cleaned.startsWith("+")) {
296	            e164 = cleaned;
297	        } else {
298	            String national = cleaned;
299	            if (national.startsWith("0")) {
300	                national = national.substring(1);
301	            }
302	            e164 = "+61" + national;
303	        }
304	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
305	            throw new InvalidOwnerFieldsException(List.of("telephone"));
306	        }
307	        return e164;
308	    }
309	
310	    /**
311	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
312	     * left unset. When a value is present it must be a syntactically valid address; the normalized
313	     * form stored and returned is the value lower-cased.
314	     *
315	     * @param email the raw email value from the request, or {@code null} when none was supplied
316	     * @return the lower-cased email, or {@code null} when no email was supplied
317	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
318	     */
319	    private String normalizeEmail(String email) {
320	        if (email == null || email.isBlank()) {
321	            return null;
322	        }
323	        if (!EMAIL_PATTERN.matcher(email).matches()) {
324	            throw new InvalidOwnerFieldsException(List.of("email"));
325	        }
326	        return email.toLowerCase(Locale.ROOT);
327	    }
328	
329	    /**
330	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
331	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
332	     * directly and is therefore independent of the punctuation a caller supplied.
333	     *
334	     * @param e164Telephone the E.164 telephone of the owner being created
335	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
336	     */
337	    private void rejectDuplicateTelephone(String e164Telephone) {
338	        boolean inUse = this.clinicService.findAllOwners().stream()
339	            .map(Owner::getTelephone)
340	            .filter(existing -> existing != null)
341	            .anyMatch(e164Telephone::equals);
342	        if (inUse) {
343	            throw new DuplicateOwnerTelephoneException(e164Telephone);
344	        }
345	    }
346	
347	    /**
348	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
349	     * last name and address, compared case-insensitively after surrounding whitespace is trimmed and
350	     * each internal run of whitespace is collapsed to a single space, so purely cosmetic differences in
351	     * spacing or letter case still count as the same household.
352	     * <p>
353	     * When the owner's last name and address already belong to at least one other owner the behaviour
354	     * depends on {@code sharesHousehold}. If it is not true the create is rejected as a duplicate
355	     * household. If it is true the create is allowed and every member of the household - the existing
356	     * owners and this joiner - is assigned the same stable {@code householdId}, which is returned on
357	     * read. When no other owner shares the last name and address no identifier is assigned.
358	     *
359	     * @param owner the owner being created
360	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
361	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
362	     *         address and {@code sharesHousehold} is not true
363	     */
364	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
365	        String lastName = normalizeHouseholdField(owner.getLastName());
366	        String address = normalizeHouseholdField(owner.getAddress());
367	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
368	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
369	                && normalizeHouseholdField(existing.getAddress()).equals(address))
370	            .toList();
371	        if (housemates.isEmpty()) {
372	            return;
373	        }
374	        if (!Boolean.TRUE.equals(sharesHousehold)) {
375	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
376	        }
377	        String householdId = generateHouseholdId(lastName, address);
378	        owner.setHouseholdId(householdId);
379	        for (Owner housemate : housemates) {
380	            if (!householdId.equals(housemate.getHouseholdId())) {
381	                housemate.setHouseholdId(householdId);
382	                this.clinicService.saveOwner(housemate);
383	            }
384	        }
385	    }
386	
387	    /**
388	     * Builds the stable identifier shared by the members of one household. It is derived purely from
389	     * the normalized last name and address, so every owner of a given household deterministically
390	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
391	     * two normalized fields joined by a single space.
392	     *
393	     * @param normalizedLastName the household's last name, already normalized for comparison
394	     * @param normalizedAddress the household's address, already normalized for comparison
395	     * @return the shared household identifier
396	     */
397	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
398	        String key = normalizedLastName + '�' + normalizedAddress;
399	        try {
400	            byte[] digest = MessageDigest.getInstance("SHA-256")
401	                .digest(key.getBytes(StandardCharsets.UTF_8));
402	            StringBuilder hex = new StringBuilder();
403	            for (byte b : digest) {
404	                hex.append(String.format("%02X", b));
405	                if (hex.length() >= 12) {
406	                    break;
407	                }
408	            }
409	            return hex.substring(0, 12);
410	        } catch (NoSuchAlgorithmException e) {
411	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
412	        }
413	    }
414	
415	    /**
416	     * Normalizes a last name or address for household comparison: surrounding whitespace is trimmed,
417	     * each internal run of whitespace is collapsed to a single space and the result is lower-cased.
418	     *
419	     * @param value the raw last name or address, or {@code null}
420	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
421	     */
422	    private String normalizeHouseholdField(String value) {
423	        if (value == null) {
424	            return "";
425	        }
426	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
427	    }
428	}
